package org.eclipse.rdf4j.common.iteration;

import static org.assertj.core.api.Assertions.assertThatExceptionOfType;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.NoSuchElementException;

import org.junit.jupiter.api.Test;

class FilterIterationTest {

	@Test
	void doesNotRecheckAvailabilityBeforeConsumingTheAdvertisedElement() {
		@SuppressWarnings("unchecked")
		CloseableIteration<String> wrapped = mock(CloseableIteration.class);
		when(wrapped.hasNext()).thenReturn(true, false);
		when(wrapped.next()).thenThrow(new NoSuchElementException("closed after reporting availability"));

		FilterIteration<String> filtered = new FilterIteration<>(wrapped) {
			@Override
			protected boolean accept(String object) {
				return true;
			}

			@Override
			protected void handleClose() {
				wrapped.close();
			}
		};

		assertThatExceptionOfType(NoSuchElementException.class).isThrownBy(filtered::hasNext);
		verify(wrapped, times(1)).hasNext();
	}
}
